"use client";
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useFinanceData } from "@/lib/api";

const NetWorthCard = () => {
  const { data, isLoading, error } = useFinanceData("/api/finance/overview/net-worth");

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  if (!data || !data.trend) return <div>No data available</div>;

  const values = data.trend.map((p: { net_worth: number }) => p.net_worth);
  const hasData = values.length > 0;
  const max = hasData ? Math.max(...values) : 1;
  const min = hasData ? Math.min(...values) : 0;
  const range = (max - min) || 1;

  const sparkline = (
    <motion.path
      d={`M0 0 L${values.length > 1 ? 100 : 50} ${35 - ((values[0] - min) / range) * 30}`}
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    />
  );

  return (
    <div className="bg-white p-4 rounded shadow">
      <h2 className="text-xl font-bold">Net Worth</h2>
      <div className="mt-4">
        <svg viewBox="0 0 100 40" width="100%" height="40">
          {sparkline}
        </svg>
      </div>
    </div>
  );
};

export default NetWorthCard;
